import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DZhUhjDB.js";const m=JSON.parse('{"title":"⚔️ Ruta: Atacante (Red Team / Pentest)","description":"","frontmatter":{"title":"⚔️ Ruta: Atacante (Red Team / Pentest)"},"headers":[],"relativePath":"modules/fundamentos/rutas/ruta-atacante.md","filePath":"modules/fundamentos/rutas/ruta-atacante.md","lastUpdated":1787330151000}'),s={name:"modules/fundamentos/rutas/ruta-atacante.md"};function n(i,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="⚔️-ruta-atacante-red-team-pentest" tabindex="-1">⚔️ Ruta: Atacante (Red Team / Pentest) <a class="header-anchor" href="#⚔️-ruta-atacante-red-team-pentest" aria-label="Permalink to &quot;⚔️ Ruta: Atacante (Red Team / Pentest)&quot;">​</a></h1><blockquote><p><strong>Para quién es esto:</strong> gente curiosa por saber cómo se rompen las cosas, que disfruta un reto técnico y quiere entender al adversario. <strong>Con responsabilidad</strong>: ética primero, ley primero,siempre.</p></blockquote><h2 id="mentalidad" tabindex="-1">Mentalidad <a class="header-anchor" href="#mentalidad" aria-label="Permalink to &quot;Mentalidad&quot;">​</a></h2><blockquote><p>&quot;Si rompo esto aquí, ¿qué roto en producción? ¿Quién se entera? ¿Cómo se defiende?&quot;</p></blockquote><p>Antes de empezar, lee <a href="./../07-etica-y-leyes"><code>../07-etica-y-leyes.md</code></a>. Si no estás cómodo con ese marco, esta ruta no es para ti.</p><h2 id="paso-1-—-roles-y-caminos" tabindex="-1">Paso 1 — Roles y caminos <a class="header-anchor" href="#paso-1-—-roles-y-caminos" aria-label="Permalink to &quot;Paso 1 — Roles y caminos&quot;">​</a></h2><p>El red team tiene varios sub-roles:</p><ul><li><strong>Pentester</strong> — auditorías cortas (1-2 semanas)</li><li><strong>Red Teamer</strong> — simulación prolongada de un adversary (semanas-meses)</li><li><strong>Bug Bounty Hunter</strong> — freelance, trabaja por recompensa</li><li><strong>Exploit Developer</strong> — escribe los exploits que otros usan</li></ul><h2 id="paso-2-—-refuerza-la-base-tecnica" tabindex="-1">Paso 2 — Refuerza la base técnica <a class="header-anchor" href="#paso-2-—-refuerza-la-base-tecnica" aria-label="Permalink to &quot;Paso 2 — Refuerza la base técnica&quot;">​</a></h2><ul><li>Lee <a href="./../03-internet-y-redes"><code>../03-internet-y-redes.md</code></a> — profunda: TCP, HTTP, DNS, TLS.</li><li>Lee <a href="./../04-sistema-operativo-y-terminal"><code>../04-sistema-operativo-y-terminal.md</code></a> — vive en la terminal.</li><li>Aprende algo de scripting: <strong>Python es obligatorio</strong>, Bash también.</li><li>Repasa <a href="./../06-vulnerabilidades"><code>../06-vulnerabilidades.md</code></a> — entiende OWASP, CVEs, CWE.</li></ul><h2 id="paso-3-—-recorre-las-carpetas-relevantes" tabindex="-1">Paso 3 — Recorre las carpetas relevantes <a class="header-anchor" href="#paso-3-—-recorre-las-carpetas-relevantes" aria-label="Permalink to &quot;Paso 3 — Recorre las carpetas relevantes&quot;">​</a></h2><p>En orden sugerido:</p><table tabindex="0"><thead><tr><th>Carpeta</th><th>Qué aporta</th></tr></thead><tbody><tr><td><a href="./../../02-pentesting-red-team/"><code>../../02-pentesting-red-team/</code></a></td><td>Punto de entrada en español con labs específicos</td></tr><tr><td><a href="./../../02-pentesting-red-team/teoria/"><code>../../02-pentesting-red-team/teoria/</code></a></td><td>Metodología pentest vs red team</td></tr><tr><td><a href="./../../02-pentesting-red-team/laboratorios/"><code>../../02-pentesting-red-team/laboratorios/</code></a></td><td>Lab concreto: pentest web</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/02-pentesting-red-team/"><code>../../01-CIBERSEGURIDAD/02-pentesting-red-team/</code></a></td><td>Pentest desde el superset</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/01-reconocimiento-osint/"><code>../../01-CIBERSEGURIDAD/01-reconocimiento-osint/</code></a></td><td>OSINT y reconocimiento</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/03-analisis-vulnerabilidades/"><code>../../01-CIBERSEGURIDAD/03-analisis-vulnerabilidades/</code></a></td><td>Análisis de bugs</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/04-explotacion-web/"><code>../../01-CIBERSEGURIDAD/04-explotacion-web/</code></a></td><td>Explotación web</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/05-post-explotacion/"><code>../../01-CIBERSEGURIDAD/05-post-explotacion/</code></a></td><td>Qué hacer después</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/07-ingenieria-social/"><code>../../01-CIBERSEGURIDAD/07-ingenieria-social/</code></a></td><td>Social engineering</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/bug-bounty-hunting/"><code>../../01-CIBERSEGURIDAD/bug-bounty-hunting/</code></a></td><td>Carrera bug bounty</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/pentester-red-team/"><code>../../01-CIBERSEGURIDAD/pentester-red-team/</code></a></td><td>Rol pentester</td></tr></tbody></table><h2 id="paso-4-—-practica-con-labs-externos-y-propios" tabindex="-1">Paso 4 — Practica con labs externos y propios <a class="header-anchor" href="#paso-4-—-practica-con-labs-externos-y-propios" aria-label="Permalink to &quot;Paso 4 — Practica con labs externos y propios&quot;">​</a></h2><p>Orden de dificultad creciente:</p><table tabindex="0"><thead><tr><th>Plataforma</th><th>Lab nivel introductorio</th></tr></thead><tbody><tr><td><a href="https://tryhackme.com/" target="_blank" rel="noreferrer">TryHackMe</a></td><td>&quot;Jr Penetration Tester&quot; path</td></tr><tr><td><a href="https://www.hackthebox.com/" target="_blank" rel="noreferrer">HackTheBox</a></td><td>Starting Point (gratis)</td></tr><tr><td><a href="https://portswigger.net/web-security" target="_blank" rel="noreferrer">PortSwigger Web Security Academy</a></td><td>Labs web GRATIS</td></tr><tr><td><a href="https://pentesterlab.com/" target="_blank" rel="noreferrer">PentesterLab</a></td><td>Web + binary</td></tr><tr><td>DVWA / WebGoat / OWASP Juice Shop (Docker)</td><td>Apps vulnerables locales</td></tr></tbody></table><p>Para labs propios del repo: <a href="./../../04-LABORATORIOS/labs-propios/"><code>../../04-LABORATORIOS/labs-propios/</code></a>, <a href="./../../04-LABORATORIOS/docker-labs/"><code>../../04-LABORATORIOS/docker-labs/</code></a> y writeups en <a href="./../../04-LABORATORIOS/ctf-writeups/"><code>../../04-LABORATORIOS/ctf-writeups/</code></a>.</p><h2 id="paso-5-—-aprende-las-fases" tabindex="-1">Paso 5 — Aprende las fases <a class="header-anchor" href="#paso-5-—-aprende-las-fases" aria-label="Permalink to &quot;Paso 5 — Aprende las fases&quot;">​</a></h2><p>Las que usan marcos como PTES, OWASP y NIST:</p><ol><li><strong>Pre-engagement</strong> — contrato, scope, reglas</li><li><strong>Reconocimiento</strong> (pasivo / activo)</li><li><strong>Enumeración</strong> — servicios, versiones, users</li><li><strong>Análisis de vulnerabilidades</strong></li><li><strong>Explotación</strong></li><li><strong>Post-explotación</strong> — pivot, persistencia</li><li><strong>Reporte</strong></li></ol><p>Las herramientas por fase:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nmap → masscan → rustscan</span></span>
<span class="line"><span>├── whatweb → Wappalyzer</span></span>
<span class="line"><span>├── gobuster → feroxbuster</span></span>
<span class="line"><span>├── Burp Suite / ZAP</span></span>
<span class="line"><span>├── Metasploit / searchsploit</span></span>
<span class="line"><span>├── LinPEAS / WinPEAS (priv esc)</span></span>
<span class="line"><span>└── BloodHound (Active Directory)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="paso-6-—-reporte-—-la-mitad-del-trabajo" tabindex="-1">Paso 6 — Reporte — la mitad del trabajo <a class="header-anchor" href="#paso-6-—-reporte-—-la-mitad-del-trabajo" aria-label="Permalink to &quot;Paso 6 — Reporte — la mitad del trabajo&quot;">​</a></h2><p>El éxito de un pentest se mide <strong>por el reporte, no por los hallazgos</strong>.</p><p>Boilerplate útil en <a href="./../../02-pentesting-red-team/portafolio/"><code>../../02-pentesting-red-team/portafolio/</code></a> y templates de informe.</p><p>Estructura recomendada:</p><ol><li>Resumen ejecutivo (1 página, sin jerga, para CISO)</li><li>Metodología</li><li>Hallazgos <ul><li>Título + severidad + CVE/CWE/CVSS</li><li>Descripción</li><li>Pasos para reproducir</li><li>Impacto</li><li>Evidencia (screenshots, HTTP requests)</li><li>Recomendación</li></ul></li><li>Conclusiones</li></ol><h2 id="paso-7-—-certificaciones-opcional-pero-muy-util" tabindex="-1">Paso 7 — Certificaciones (opcional pero muy útil) <a class="header-anchor" href="#paso-7-—-certificaciones-opcional-pero-muy-util" aria-label="Permalink to &quot;Paso 7 — Certificaciones (opcional pero muy útil)&quot;">​</a></h2><p>Orden sugerido:</p><ol><li><strong>eJPT</strong> (eLearnSecurity Junior Penetration Tester) — primer paso accesible.</li><li><strong>CompTIA PenTest+</strong> — base general.</li><li><strong>PNPT</strong> (Practical Network Penetration Tester) — práctico.</li><li><strong>OSCP</strong> — la referencia de facto en pentest.</li><li><strong>OSWE</strong> — si te enfocas en web.</li><li><strong>CRTO</strong> — si te enfocas en red team moderno.</li><li><strong>CRTP</strong> — Active Directory.</li></ol><p>Ve <a href="./../../05-RECURSOS/certificaciones/"><code>../../05-RECURSOS/certificaciones/</code></a> y <a href="./../../05-RECURSOS/cheatsheets/"><code>../../05-RECURSOS/cheatsheets/</code></a>.</p><h2 id="paso-8-—-tu-carrera-especializate" tabindex="-1">Paso 8 — Tu carrera / especialízate <a class="header-anchor" href="#paso-8-—-tu-carrera-especializate" aria-label="Permalink to &quot;Paso 8 — Tu carrera / especialízate&quot;">​</a></h2><ul><li><strong>Web</strong>: bug bounty, PortSwigger Academy, HackerOne</li><li><strong>Redes/Infrastructure</strong>: OSCP, CRTP</li><li><strong>Active Directory</strong>: BloodHound, Mimikatz (en labs)</li><li><strong>Mobile</strong>: Android, iOS</li><li><strong>Hardware/IoT</strong>: cosas raras</li><li><strong>Social engineering</strong>: phishing, vishing (ojo: solo autorizado)</li></ul><h2 id="✏️-plan-de-30-dias-para-empezar" tabindex="-1">✏️ Plan de 30 días para empezar <a class="header-anchor" href="#✏️-plan-de-30-dias-para-empezar" aria-label="Permalink to &quot;✏️ Plan de 30 días para empezar&quot;">​</a></h2><ul><li><strong>Semana 1:</strong> instala Kali o tira una VM Ubuntu. Aprende 5 comandos diarios. Termina <a href="./../04-sistema-operativo-y-terminal"><code>../04-sistema-operativo-y-terminal.md</code></a>.</li><li><strong>Semana 2:</strong> completa TryHackMe &quot;Jr Penetration Tester&quot; path hasta la mitad. Lee <a href="./../08-herramientas-esenciales"><code>../08-herramientas-esenciales.md</code></a>.</li><li><strong>Semana 3:</strong> resuelve 3 retos de PortSwigger Academy (XSS, SQLi, SSRF). Lee <a href="./../06-vulnerabilidades"><code>../06-vulnerabilidades.md</code></a> a fondo.</li><li><strong>Semana 4:</strong> abre <a href="./../../02-pentesting-red-team/"><code>../../02-pentesting-red-team/</code></a> y haz el lab de <a href="./../../02-pentesting-red-team/laboratorios/"><code>../../02-pentesting-red-team/laboratorios/</code></a>. Escribe tu primer mini-reporte.</li></ul><blockquote><p>🟣 <strong>Bonus:</strong> combina Red+Blue en <a href="./../../04-purple-team-colaboracion/"><code>../../04-purple-team-colaboracion/</code></a>.</p></blockquote><hr><blockquote><p>⏪ <strong>Volver al mapa:</strong> <a href="./../09-como-seguir-este-repo"><code>../09-como-seguir-este-repo.md</code></a> 🛡️ <strong>Otra ruta:</strong> <a href="./ruta-defensor"><code>./ruta-defensor.md</code></a> si quieres defender.</p></blockquote>`,38)])])}const b=a(s,[["render",n]]);export{m as __pageData,b as default};
